insert into abm_plantillas (giro,canal,nombre,orden,asunto,cuerpo,formato,objetivo,ruta) values
('cadenas','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para tiendas de moda. Lo nuestro es el control de talla y color entre tiendas[[si sucursales]], como sus {{sucursales}} sucursales[[/si]]. ¿Con quién se puede ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('cadenas','whatsapp','sigue',2,null,'Vuelvo una vez y ya no insisto. Con varias tiendas lo que duele es la talla: se acaba la mediana en una, sigue colgada en otra y nadie se entera hasta que la clienta la pide. ¿Me pasa el correo de quien ve compras e inventario?','texto','WhatsApp · sigue','ambas'),
('cadenas','whatsapp','cierra',3,null,'Con esta ya no le insisto más. Si algún día quieren ver en una sola pantalla lo que hay en todas las tiendas, aquí queda mi número. Gracias por leerme y buenas ventas.','texto','WhatsApp · cierra','ambas'),
('boutiques','whatsapp','abre',1,null,'Hola[[si persona]] {{persona}}[[/si]], buen día. Te escribo de Sacs, un sistema mexicano de inventario y punto de venta para tiendas de moda. Sé que ahí están atendiendo, así que solo una pregunta: ¿quién ve el inventario en {{nombre}} y cómo lo contacto?','texto','WhatsApp · abre','ambas'),
('boutiques','whatsapp','sigue',2,null,'Insisto una vez y ya. En boutique multimarca lo difícil es saber qué talla y qué color queda de cada marca sin hablarle a la otra tienda. ¿Me pasas un correo o el nombre de quien decide eso?','texto','WhatsApp · sigue','ambas'),
('boutiques','whatsapp','cierra',3,null,'Última y te dejo trabajar. Si algún día quieren ver tallas, colores y marcas en un solo lugar, aquí sigue mi número. Gracias por el tiempo.','texto','WhatsApp · cierra','ambas'),
('renta','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para tiendas de moda. Nos buscan mucho negocios de renta, por saber qué días está libre cada pieza. ¿Con quién puedo ver eso y por dónde?','texto','WhatsApp · abre','ambas'),
('renta','whatsapp','sigue',2,null,'Vuelvo una vez nada más. Lo que más nos piden en renta es no apartar dos veces la misma pieza, y no perder la que ya volvió de tintorería sin que nadie lo supiera. ¿Me deja el correo o el nombre de quien lleva los apartados?','texto','WhatsApp · sigue','ambas'),
('renta','whatsapp','cierra',3,null,'Con esta cierro y no vuelvo a insistir. Si algún día quieren ver el calendario de cada prenda, apartada, en tintorería o libre, aquí queda mi número. Gracias por leerme.','texto','WhatsApp · cierra','ambas'),
('novias','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para tiendas de moda. Con novias nos buscan por los apartados: modelo, talla y fecha de boda. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('novias','whatsapp','sigue',2,null,'Insisto una vez y ya. En novias todo cuelga de una fecha: el vestido que se pide al proveedor, las pruebas, el anticipo y el saldo. Si una se recorre, se recorren todas. ¿Me pasa el correo de quien lleva los apartados?','texto','WhatsApp · sigue','ambas'),
('novias','whatsapp','cierra',3,null,'Aquí lo dejo, sin insistir más. Si alguna temporada quieren llevar cada novia con su fecha, sus pruebas y sus abonos en un solo lugar, este número sigue abierto. Gracias.','texto','WhatsApp · cierra','ambas'),
('zapaterias','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario y punto de venta para calzado. El tema es el número que falta justo cuando el cliente ya lo pidió. ¿Con quién puedo verlo y por dónde?','texto','WhatsApp · abre','ambas'),
('zapaterias','whatsapp','sigue',2,null,'Vuelvo una vez y ya. Un modelo son ocho o doce números: se acaban del 25 al 27 y quedan colgados los extremos. El modelo sigue con existencia, pero ya está muerto. ¿Me da el correo de quien hace las compras?','texto','WhatsApp · sigue','ambas'),
('zapaterias','whatsapp','cierra',3,null,'Con esta cierro. Si más adelante quieren ver qué números se están acabando antes de que se vacíe el centro de la curva, aquí estoy. Gracias por el tiempo.','texto','WhatsApp · cierra','ambas'),
('western','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}}[[si ciudad]], allá en {{ciudad}},[[/si]] de parte de Sacs, sistema mexicano de inventario para negocios de moda. Lo nuestro en bota es llevar los pares por número, horma y piel. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('western','whatsapp','sigue',2,null,'Vuelvo una vez y ya. Un solo modelo se le vuelve setenta pares entre números, hormas y pieles, y no todos valen igual: un par de avestruz cuesta como cinco de res. ¿Me pasa el correo del dueño o de quien ve las compras?','texto','WhatsApp · sigue','ambas'),
('western','whatsapp','cierra',3,null,'Con esta ya no le insisto. Si algún día quieren ver sus pares por horma y por piel, tienda por tienda, aquí queda mi número. Gracias y buena feria.','texto','WhatsApp · cierra','ambas'),
('vintage','whatsapp','abre',1,null,'Hola[[si persona]] {{persona}}[[/si]], buen día. Te escribo de Sacs, un sistema mexicano de inventario y punto de venta para moda. Nos buscan tiendas donde cada prenda es única. Sé que estás atendiendo: ¿quién ve ese tema en {{nombre}} y cómo le escribo?','texto','WhatsApp · abre','ambas'),
('vintage','whatsapp','sigue',2,null,'Insisto una sola vez. Lo que más nos piden en vintage es que la pieza vendida en tienda se apague sola en Instagram y en línea, y el corte de lo que le toca a cada consignante. ¿Me pasas un correo o el nombre de quien decide?','texto','WhatsApp · sigue','ambas'),
('vintage','whatsapp','cierra',3,null,'Ya no molesto más. Si en algún momento quieren dar de alta cada pieza una sola vez y venderla en todos lados sin duplicarse, aquí sigo. Gracias por leerme.','texto','WhatsApp · cierra','ambas'),
('joyeria','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para moda y joyería. Lo nuestro es el costeo cuando el oro se mueve y el precio se queda quieto. ¿Con quién puedo verlo y por dónde?','texto','WhatsApp · abre','ambas'),
('joyeria','whatsapp','sigue',2,null,'Vuelvo una vez nada más. El precio de una pieza son partes que se mueven solas: oro por quilate, plata por ley, gemas y mano de obra. Casi siempre vive en un Excel de una sola persona. ¿Me pasa el correo de quien saca los precios?','texto','WhatsApp · sigue','ambas'),
('joyeria','whatsapp','cierra',3,null,'Aquí lo dejo, sin insistir. Si algún día quieren que sus precios sigan al metal sin recostear a mano, este número sigue abierto. Gracias por su tiempo.','texto','WhatsApp · cierra','ambas'),
('charro','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para negocios de moda. Nos toca mucho el traje a la medida: pedidos de grupo, anticipos y tiempos de taller. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('charro','whatsapp','sigue',2,null,'Insisto una vez y ya. Cuando un ballet pide treinta trajes para la misma fecha, por dentro son treinta medidas, con su paño y su botonadura, y el dinero entra partido en tres. ¿Me pasa el correo o el nombre de quien lleva los pedidos?','texto','WhatsApp · sigue','ambas'),
('charro','whatsapp','cierra',3,null,'Con esta cierro. Si en alguna temporada quieren ver cada traje del pedido con su avance y su anticipo, aquí queda mi número. Gracias y buena temporada.','texto','WhatsApp · cierra','ambas'),
('scrubs','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario y punto de venta para moda y uniformes. El tema es contar por talla y por color, con el bordado aparte. ¿Con quién puedo verlo y por dónde?','texto','WhatsApp · abre','ambas'),
('scrubs','whatsapp','sigue',2,null,'Vuelvo una vez y ya. Seis tallas por ocho colores ya son cuarenta y ocho cosas distintas que contar, y en bodega siempre quedan piezas buenas sueltas, sin su par. ¿Me pasa el correo de quien lleva el inventario?','texto','WhatsApp · sigue','ambas'),
('scrubs','whatsapp','cierra',3,null,'Aquí lo dejo. Si algún día quieren ver sus piezas por talla y color, y el bordado con su costo y su fecha, sigo en este número. Gracias por leerme.','texto','WhatsApp · cierra','ambas'),
('telas','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario y punto de venta para moda. Con telas lo nuestro es llevar rollo y metro al mismo tiempo. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('telas','whatsapp','sigue',2,null,'Vuelvo una vez nada más. El rollo no se acaba, se parte: quedan 2.80 metros que ya no le sirven a quien pide cuatro y siguen contando a precio de rollo. Y abajo la mercería. ¿Me pasa el correo de quien decide?','texto','WhatsApp · sigue','ambas'),
('telas','whatsapp','cierra',3,null,'Con esta ya no molesto. Si algún día quieren ver cuánto quedó suelto en cada rollo, y el mayoreo y el menudeo en el mismo mostrador, aquí sigo. Gracias por su tiempo.','texto','WhatsApp · cierra','ambas'),
('tallas','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}}[[si ciudad]], allá en {{ciudad}},[[/si]] de parte de Sacs, sistema mexicano de inventario y punto de venta para moda. Trabajamos mucho con curvas largas de talla. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('tallas','whatsapp','sigue',2,null,'Insisto una vez y ya. En el perchero el modelo se ve lleno, pero la 2XL y la 3XL, que son las que salen, llevan semanas en cero, y la clienta que no la encuentra dos veces ya no vuelve. ¿Me pasa el correo de quien compra?','texto','WhatsApp · sigue','ambas'),
('tallas','whatsapp','cierra',3,null,'Cierro con esta, sin insistir más. Si algún día quieren que el sistema avise cuando se está acabando la talla que más sale, aquí queda mi número. Gracias por leerme.','texto','WhatsApp · cierra','ambas'),
('operadores','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}}[[si ciudad]], allá en {{ciudad}},[[/si]] de parte de Sacs, sistema mexicano de inventario y punto de venta para moda. Nos buscan operaciones que venden marcas que no son suyas. ¿Con quién puedo ver ese tema y por dónde?','texto','WhatsApp · abre','ambas'),
('operadores','whatsapp','sigue',2,null,'Vuelvo una vez y ya. Lo complicado es que cada pieza trae apellido: de qué marca es, con qué comisión entró y hasta cuándo se queda, encima de talla y color. ¿Me pasa el correo de quien arma la cuenta de cada marca?','texto','WhatsApp · sigue','ambas'),
('operadores','whatsapp','cierra',3,null,'Aquí lo dejo, sin insistir. Si en algún momento quieren el corte por marca saliendo solo, sin Excel aparte, este número sigue abierto. Gracias por su tiempo.','texto','WhatsApp · cierra','ambas'),
('aliados','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para negocios de moda. No vengo a venderle nada: traigo una propuesta de convenio para sus alumnas. ¿Con quién puedo verla y por dónde?','texto','WhatsApp · abre','ambas'),
('aliados','whatsapp','sigue',2,null,'Insisto una vez y ya. La idea es simple: sus alumnas reciben de su parte un diagnóstico gratis de inventario, y de las que se queden con el sistema a usted le toca comisión. Usted no opera nada. ¿Le paso el detalle por correo?','texto','WhatsApp · sigue','ambas'),
('aliados','whatsapp','cierra',3,null,'Con esta cierro. Si más adelante le interesa ofrecerles ese diagnóstico a sus alumnas, aquí queda mi número. Gracias por leerme y mucho éxito con el programa.','texto','WhatsApp · cierra','ambas'),
('canal','whatsapp','abre',1,null,'Buen día. Le escribo a {{nombre}} de parte de Sacs, sistema mexicano de inventario para negocios de moda. No vengo a venderle a usted: traigo un convenio para sus clientas. ¿Con quién puedo platicarlo y por dónde le escribo?','texto','WhatsApp · abre','ambas'),
('canal','whatsapp','sigue',2,null,'Vuelvo una vez nada más. Las clientas que compran a ojo se quedan con el dinero parado en piso y dejan de pedirle. A cada una le damos diagnóstico gratis de su parte, y a usted le queda comisión. ¿Le mando el detalle por correo?','texto','WhatsApp · sigue','ambas'),
('canal','whatsapp','cierra',3,null,'Aquí lo dejo, sin insistir. Si algún día quiere ofrecerles ese diagnóstico a sus clientas, este número sigue abierto. Gracias por su tiempo.','texto','WhatsApp · cierra','ambas');